result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "pyawk.py", "content": "#!/usr/bin/env python3
"""pyawk.py -- a small AWK subset interpreter.

Usage: python pyawk.py 'program' [file]

Supported program syntax:
    BEGIN{action}  END{action}  [/regex/]{action}

Actions support:
    print expr [, expr ...]     (args joined by OFS, default " ")
    $0, $1 .. $9                (fields; split on runs of whitespace)
    NF                          (number of fields)
    NR                          (record number, 1-based)
    "str" juxtaposition         (string concatenation)
    name += expr                (named counter variables, default 0)
Semicolons separate statements.
"""

import re
import sys


# ---------------------------------------------------------------- tokenizer

class Token:
    def __init__(self, kind, value):
        self.kind = kind      # WORD STR REGEX FIELD NUM LBRACE RBRACE SEMI COMMA PLUSEQ EOF
        self.value = value

    def __repr__(self):
        return f"Token({self.kind}, {self.value!r})"


def tokenize(src):
    toks = []
    i, n = 0, len(src)
    while i < n:
        c = src[i]
        if c.isspace():
            i += 1
            continue
        if c == '"':
            j = i + 1
            buf = []
            while j < n and src[j] != '"':
                if src[j] == '\\' and j + 1 < n:
                    esc = src[j + 1]
                    buf.append({'n': '\n', 't': '\t', '\\': '\\', '"': '"'}.get(esc, esc))
                    j += 2
                else:
                    buf.append(src[j])
                    j += 1
            if j >= n:
                raise SyntaxError("unterminated string literal")
            toks.append(Token("STR", "".join(buf)))
            i = j + 1
        elif c == '/':
            j = i + 1
            buf = []
            while j < n and src[j] != '/':
                if src[j] == '\\' and j + 1 < n:
                    buf.append(src[j:j + 2])
                    j += 2
                else:
                    buf.append(src[j])
                    j += 1
            if j >= n:
                raise SyntaxError("unterminated regex literal")
            toks.append(Token("REGEX", "".join(buf)))
            i = j + 1
        elif c == '$':
            j = i + 1
            while j < n and src[j].isdigit():
                j += 1
            if j == i + 1:
                raise SyntaxError("'%' must be followed by a field number")
            toks.append(Token("FIELD", int(src[i + 1:j])))
            i = j
        elif c.isdigit() or (c == '.' and i + 1 < n and src[i + 1].isdigit()):
            j = i
            while j < n and (src[j].isdigit() or src[j] == '.'):
                j += 1
            text = src[i:j]
            toks.append(Token("NUM", float(text) if '.' in text else int(text)))
            i = j
        elif src.startswith("+=", i):
            toks.append(Token("PLUSEQ", "+="))
            i += 2
        elif c == '{':
            toks.append(Token("LBRACE", c)); i += 1
        elif c == '}':
            toks.append(Token("RBRACE", c)); i += 1
        elif c == ';':
            toks.append(Token("SEMI", c)); i += 1
        elif c == ',':
            toks.append(Token("COMMA", c)); i += 1
        elif c.isalpha() or c == '_':
            j = i
            while j < n and (src[j].isalnum() or src[j] == '_'):
                j += 1
            toks.append(Token("WORD", src[i:j]))
            i = j
        else:
            raise SyntaxError(f"unexpected character {c!r}")
    toks.append(Token("EOF", None))
    return toks


# ------------------------------------------------------------------ parser
#
# AST nodes (plain tuples/dicts):
#   ("print", [expr, ...])
#   ("pluseq", name, expr)
# expressions:
#   ("concat", [primary, ...])   primary: ("str", s) ("field", k)
#                                     ("nf",) ("nr",) ("num", v) ("var", name)

class Parser:
    def __init__(self, tokens):
        self.toks = tokens
        self.pos = 0

    def peek(self):
        return self.toks[self.pos]

    def next(self):
        t = self.toks[self.pos]
        self.pos += 1
        return t

    def expect(self, kind):
        t = self.next()
        if t.kind != kind:
            raise SyntaxError(f"expected {kind}, got {t.kind} ({t.value!r})")
        return t

    def parse_program(self):
        begin = end = None
        rules = []
        while self.peek().kind != "EOF":
            t = self.peek()
            if t.kind == "WORD" and t.value == "BEGIN":
                self.next()
                begin = self.parse_block()
            elif t.kind == "WORD" and t.value == "END":
                self.next()
                end = self.parse_block()
            elif t.kind == "REGEX":
                pat = re.compile(self.next().value)
                rules.append((pat, self.parse_block()))
            elif t.kind == "LBRACE":
                rules.append((None, self.parse_block()))
            elif t.kind == "SEMI":
                self.next()
            else:
                raise SyntaxError(f"unexpected token {t.value!r} at top level")
        return begin, rules, end

    def parse_block(self):
        self.expect("LBRACE")
        stmts = []
        while self.peek().kind != "RBRACE":
            stmts.append(self.parse_stmt())
            if self.peek().kind == "SEMI":
                self.next()
        self.expect("RBRACE")
        return stmts

    def parse_stmt(self):
        t = self.peek()
        if t.kind == "WORD" and t.value == "print":
            self.next()
            args = []
            if self.peek().kind not in ("RBRACE", "SEMI"):
                args.append(self.parse_expr())
                while self.peek().kind == "COMMA":
                    self.next()
                    args.append(self.parse_expr())
            return ("print", args)
        if t.kind == "WORD" and self.toks[self.pos + 1].kind == "PLUSEQ":
            name = self.next().value
            self.next()
            return ("pluseq", name, self.parse_expr())
        raise SyntaxError(f"unsupported statement near {t.value!r}")

    def parse_expr(self):
        parts = [self.parse_primary()]
        while True:
            k = self.peek().kind
            if k in ("STR", "FIELD", "NUM") or (
                k == "WORD" and self.peek().value in ("NF", "NR") or
                k == "WORD" and self._is_var_ahead()
            ):
                # juxtaposition: another primary follows
                if self.peek().kind == "WORD" and self.peek().value not in ("NF", "NR"):
                    break
                parts.append(self.parse_primary())
            else:
                break
        return ("concat", parts)

    def _is_var_ahead(self):
        """A bare word is a variable reference only when not a keyword."""
        return self.peek().value not in ("print", "BEGIN", "END")

    def parse_primary(self):
        t = self.next()
        if t.kind == "STR":
            return ("str", t.value)
        if t.kind == "FIELD":
            return ("field", t.value)
        if t.kind == "NUM":
            return ("num", t.value)
        if t.kind == "WORD":
            if t.value == "NF":
                return ("nf",)
            if t.value == "NR":
                return ("nr",)
            return ("var", t.value)
        raise SyntaxError(f"unexpected token {t.value!r} in expression")


# --------------------------------------------------------------- evaluator

class Interp:
    def __init__(self, begin, rules, end, ofs=" "):
        self.begin = begin
        self.rules = rules
        self.end = end
        self.ofs = ofs
        self.vars = {}

    # -- value helpers ----------------------------------------------------
    @staticmethod
    def tonum(v):
        if isinstance(v, (int, float)):
            return v
        if isinstance(v, str):
            try:
                return int(v)
            except ValueError:
                try:
                    return float(v)
                except ValueError:
                    return 0
        return 0

    @staticmethod
    def tostr(v):
        if isinstance(v, bool):  # guard, shouldn't occur
            return str(v)
        if isinstance(v, float) and v.is_integer():
            return str(int(v))
        return str(v)

    # -- execution --------------------------------------------------------
    def run(self, lines):
        self.fields = [""] * 9
        self.record = ""
        self.nf = 0
        self.nr = 0
        self.out = []

        if self.begin is not None:
            self.exec_stmts(self.begin)

        for line in lines:
            self.record = line.rstrip("\n")
            self.fields = self.record.split()
            self.nf = len(self.fields)
            self.nr += 1
            for pat, stmts in self.rules:
                if pat is None or pat.search(self.record):
                    self.exec_stmts(stmts)

        if self.end is not None:
            self.exec_stmts(self.end)

        return "".join(self.out)

    def exec_stmts(self, stmts):
        for s in stmts:
            self.exec_stmt(s)

    def exec_stmt(self, s):
        op = s[0]
        if op == "print":
            args = s[1]
            if not args:
                text = self.record
            else:
                text = self.ofs.join(self.tostr(self.eval(e)) for e in args)
            self.out.append(text + "\n")
        elif op == "pluseq":
            _, name, expr = s
            self.vars[name] = self.vars.get(name, 0) + self.tonum(self.eval(expr))
        else:
            raise RuntimeError(f"unknown statement {op}")

    def eval(self, e):
        if e[0] == "concat":
            return "".join(self.eval_part(p) for p in e[1])
        return self.eval_part(e)

    def eval_part(self, p):
        k = p[0]
        if k == "str":
            return p[1]
        if k == "field":
            idx = p[1]
            return self.fields[idx] if 0 <= idx < len(self.fields) else ""
        if k == "nf":
            return self.nf
        if k == "nr":
            return self.nr
        if k == "num":
            return p[1]
        if k == "var":
            return self.vars.get(p[1], 0)
        raise RuntimeError(f"unknown expression {k}")


# --------------------------------------------------------------------- main

def run_program(program_text, lines):
    begin, rules, end = Parser(tokenize(program_text)).parse_program()
    return Interp(begin, rules, end).run(lines)


def main(argv):
    if len(argv) < 2:
        sys.stderr.write("usage: python pyawk.py 'program' [file]\n")
        return 2
    program_text = argv[1]
    if len(argv) > 2:
        with open(argv[2], encoding="utf-8") as f:
            lines = f.readlines()
    else:
        lines = sys.stdin.readlines()
    sys.stdout.write(run_program(program_text, lines))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
